# Write python code which generates config files for pair_ids 1-9, per dataset and model variant

from pathlib import Path

config_template = \
"""dataset:
  name: {dataset}
  pair_id:
  - {pair_id}
model:
  name: moirai
  variant: {variant}
  recon_ctx: {recon_ctx}
  validation: 0
  device: {device}
  batch_size: {batch_size}
"""

# Define the datasets, model variants and pair_ids
# (KS_Official, Lorenz_Official, seismo configs were generated by an earlier version of this
# script without `variant`; run.py treats those as the default moirai2 variant.)
datasets = ["pke-hpmr", "dynasty", "msfr", "mhd-2cyls"]
variants = ["moirai-moe", "moirai2"]
pair_ids = list(range(1, 10))  # 1-9
recon_ctx = 50
device = "cuda"

# moirai / moirai-moe forecast all channels jointly as ONE multivariate sequence (the original
# method). moirai2 is univariate: each channel is forecast independently.

# moirai2 batches over channels (each channel is its own univariate series)
batch_size = {
    "pke-hpmr": 32,
    "dynasty": 32,
    "msfr": 512,
    "mhd-2cyls": 512,
}

# Get the directory where this script is located
config_dir = Path(__file__).parent / 'config'
config_dir.mkdir(parents=True, exist_ok=True)

# Generate config files
count = 0
for dataset in datasets:
    for variant in variants:
        for pair_id in pair_ids:
            # Format the template with current values
            config_content = config_template.format(
                dataset=dataset,
                pair_id=pair_id,
                variant=variant,
                recon_ctx=recon_ctx,
                device=device,
                batch_size=batch_size[dataset] if variant == "moirai2" else 32,
            )

            # Create filename
            filename = f"config_{dataset}_{variant}_p{pair_id}.yaml"
            filepath = config_dir / filename

            # Write the config file
            with open(filepath, 'w') as f:
                f.write(config_content)

            print(f"Generated: {filename}")
            count += 1

print(f"Generated {count} config files")
